from collections import deque
seen8=set(); comps8=[]
for r in range(H):
 for c in range(W):
  if (r,c) in coords or (r,c) in seen8: continue
  q=deque([(r,c)]);seen8.add((r,c));ccs=[];edge=False
  while q:
   p=q.popleft();ccs.append(p);rr,cc=p
   if rr in (0,H-1) or cc in (0,W-1):edge=True
   for nr in range(rr-1,rr+2):
    for nc in range(cc-1,cc+2):
     if 0<=nr<H and 0<=nc<W and (nr,nc) not in coords and (nr,nc) not in seen8:seen8.add((nr,nc));q.append((nr,nc))
  comps8.append((edge,ccs))
